import pytest
from isort.settings import _get_config_data

def test_get_config_data_toml_valid():
    result = _get_config_data('valid_config.toml', ('section1', 'section2'))
    expected = {'key1': 'value1', 'key2': 'value2', 'source': 'valid_config.toml'}
    assert result == expected

def test_get_config_data_editorconfig_valid():
    result = _get_config_data('valid_config.editorconfig', ('[*]',))
    expected = {'indent_style': 'space', 'indent_size': '4', 'source': 'valid_config.editorconfig'}
    assert result == expected

def test_get_config_data_file_not_found():
    with pytest.raises(FileNotFoundError):
        _get_config_data('non_existent_file.toml', ('section1',))

def test_get_config_data_empty_sections():
    result = _get_config_data('valid_config.toml', ())
    expected = {'source': 'valid_config.toml'}
    assert result == expected

def test_get_config_data_no_sections_in_editorconfig():
    result = _get_config_data('empty_config.editorconfig', ('[*]',))
    expected = {'source': 'empty_config.editorconfig'}
    assert result == expected

def test_get_config_data_invalid_boolean_conversion():
    result = _get_config_data('config_with_bool.toml', ('force_grid_wrap',))
    expected = {'force_grid_wrap': 2, 'source': 'config_with_bool.toml'}  # assuming 'true' was incorrectly fed
    assert result == expected
